func check(ok bool, message string) {
	if !ok {
		panic(message)
	}
}

func main() {
	// Predict a first value
	{
		greeting := "Hello, Go"
		check(greeting == "Hello, Go", "greeting")
	}

	// Compute before formatting
	{
		total := 2 + 3
		line := fmt.Sprintf("total=%d", total)
		check(total == 5 && line == "total=5", "format")
	}

// Trace statement order
{
	count := 1
	count++
	count *= 3
	check(count == 6, "order")
}

// Distinguish zero initialization
{
	var n int
	var ready bool
	check(n == 0 && !ready, "zero values")
}

	// Repair a naming assumption
	{
		total := 3
		Total := 7
		check(total != Total, "case-sensitive names")
	}

	// Transfer to a receipt
	{
		items, unit := 4, 6
		receipt := fmt.Sprintf("amount=%d", items*unit)
		check(receipt == "amount=24", "receipt")
	}
	fmt.Println("All lesson checks passed.")
}

// Drain before iteration ends
{
	ch := make(chan int, 2)
	ch <- 2
	ch <- 3
	close(ch)
	sum := 0
	for v := range ch {
		sum += v
	}
	check(sum == 5, "drain")
}

// Distinguish zero from closed
{
	ch := make(chan int, 1)
	ch <- 0
	close(ch)
	a, okA := <-ch
	b, okB := <-ch
	check(a == 0 && b == 0 && okA && !okB, "closed presence")
}

// Use sender ownership
{
	ch := make(chan int)
	go produce(ch)
	count := 0
	for range ch {
		count++
	}
	check(count == 2, "producer close")
}

// Disable a nil select arm
{
	var disabled <-chan int
	ready := make(chan struct{})
	close(ready)
	selected := false
	select {
	case <-disabled:
		panic("nil selected")
	case <-ready:
		selected = true
	}
	check(selected, "nil arm")
}

	// Transfer independent message storage
	{
		original := []int{1}
		ch := make(chan []int, 1)
		ch <- append([]int(nil), original...)
		original[0] = 9
		received := <-ch
		check(received[0] == 1, "copy")
	}
	fmt.Println("All lesson checks passed.")
}

func plan(wanted int, exists bool, current int) string {
	if wanted < 0 {
		return "invalid"
	}
	if !exists {
		return "create"
	}
	if wanted != current {
		return "update"
	}
	return "none"
}

// Plan a missing child
{
	check(plan(3, false, 0) == "create", "missing child")
}

// Plan a changed child
{
	check(plan(3, true, 2) == "update", "changed child")
}

// Make convergence a no-op
{
	check(plan(3, true, 3) == "none", "converged")
}

// Reject invalid desired state
{
	check(plan(-1, true, 2) == "invalid", "invalid intent")
}

// Simulate a converging step
{
	current := 1
	check(plan(3, true, current) == "update", "first plan")
	current = 3
	check(plan(3, true, current) == "none", "second plan")
}

	// Transfer scale-to-zero
	{
		check(plan(0, true, 2) == "update" && plan(0, true, 0) == "none", "zero scale")
	}
	fmt.Println("All lesson checks passed.")
}
